package io.forgeloop.control.domain;
import jakarta.persistence.*;
@Entity public class DeliveryTask { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @ManyToOne(optional=false) private FeatureRun run; private String role; private String title; @Enumerated(EnumType.STRING) private TaskState state; private int attemptBudget=2; private int attempts; protected DeliveryTask(){} DeliveryTask(FeatureRun run,String role,String title){this.run=run;this.role=role;this.title=title;this.state=TaskState.PENDING;} public void transition(TaskState to){if(state==TaskState.VERIFIED||state==TaskState.FAILED)throw new IllegalStateException("Terminal task cannot transition");if(to==TaskState.REPAIR_QUEUED&&++attempts>attemptBudget){state=TaskState.FAILED;return;}state=to;} public String getId(){return id;} public String getRole(){return role;} public String getTitle(){return title;} public TaskState getState(){return state;} public int getAttemptBudget(){return attemptBudget;} public int getAttempts(){return attempts;} }
